/* Twitter Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="twitter-light"] {
  --background: rgb(255, 255, 255);
  --foreground: rgb(16, 20, 24);
  --card: rgb(248, 248, 248);
  --card-foreground: rgb(16, 20, 24);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(16, 20, 24);
  --primary: rgb(30, 156, 240);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(16, 20, 24);
  --secondary-foreground: rgb(255, 255, 255);
  --muted: rgb(228, 228, 228);
  --muted-foreground: rgb(16, 20, 24);
  --accent: rgb(226, 236, 249);
  --accent-foreground: rgb(30, 156, 240);
  --destructive: rgb(245, 30, 45);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(226, 233, 237);
  --input: rgb(248, 248, 248);
  --ring: rgb(24, 160, 242);
  --chart-1: rgb(30, 156, 240);
  --chart-2: rgb(0, 184, 122);
  --chart-3: rgb(247, 185, 39);
  --chart-4: rgb(32, 192, 101);
  --chart-5: rgb(224, 33, 93);
  --radius: 1.3rem;
  --sidebar: rgb(248, 248, 248);
  --sidebar-foreground: rgb(16, 20, 24);
  --sidebar-primary: rgb(30, 156, 240);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(226, 236, 249);
  --sidebar-accent-foreground: rgb(30, 156, 240);
  --sidebar-border: rgb(226, 233, 238);
  --sidebar-ring: rgb(24, 160, 242);
  --font-sans: Open Sans, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Menlo, monospace;
  --shadow-color: rgba(29, 161, 242, 0.15);
  --shadow-opacity: 0;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
  --shadow-xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
  --shadow-sm:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-md:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 2px 4px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-lg:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 4px 6px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-xl:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 8px 10px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-2xl: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="twitter-dark"] {
  --background: rgb(0, 0, 0);
  --foreground: rgb(232, 232, 232);
  --card: rgb(23, 24, 29);
  --card-foreground: rgb(219, 219, 219);
  --popover: rgb(0, 0, 0);
  --popover-foreground: rgb(232, 232, 232);
  --primary: rgb(30, 156, 240);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(242, 242, 242);
  --secondary-foreground: rgb(16, 20, 24);
  --muted: rgb(24, 24, 24);
  --muted-foreground: rgb(112, 117, 122);
  --accent: rgb(7, 21, 32);
  --accent-foreground: rgb(30, 156, 240);
  --destructive: rgb(245, 30, 45);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(38, 38, 38);
  --input: rgb(33, 48, 60);
  --ring: rgb(24, 160, 242);
  --chart-1: rgb(30, 156, 240);
  --chart-2: rgb(0, 184, 122);
  --chart-3: rgb(247, 185, 39);
  --chart-4: rgb(32, 192, 101);
  --chart-5: rgb(224, 33, 93);
  --radius: 1.3rem;
  --sidebar: rgb(23, 24, 29);
  --sidebar-foreground: rgb(219, 219, 219);
  --sidebar-primary: rgb(24, 160, 242);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(7, 21, 32);
  --sidebar-accent-foreground: rgb(30, 156, 240);
  --sidebar-border: rgb(57, 68, 76);
  --sidebar-ring: rgb(24, 160, 242);
  --font-sans: Open Sans, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Menlo, monospace;
  --shadow-color: rgba(29, 161, 242, 0.25);
  --shadow-opacity: 0;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
  --shadow-xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
  --shadow-sm:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-md:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 2px 4px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-lg:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 4px 6px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-xl:
    0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
    0px 8px 10px -1px hsl(202.82 89.12% 53.14% / 0);
  --shadow-2xl: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
}
